import{_ as r,o as a,c as t,aj as i}from"./chunks/framework.C6uXqnaX.js";const q=JSON.parse('{"title":"Child query result is required but no value is available.","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"errors/NG0951.md","filePath":"errors/NG0951.md"}'),s={name:"errors/NG0951.md"};function l(o,e,c,u,n,d){return a(),t("div",null,e[0]||(e[0]=[i('<h1 id="child-query-result-is-required-but-no-value-is-available" tabindex="-1">Child query result is required but no value is available. <a class="header-anchor" href="#child-query-result-is-required-but-no-value-is-available" aria-label="Permalink to &quot;Child query result is required but no value is available.&quot;">​</a></h1><p>Required child query (<code>contentChild.required</code> or <code>viewChild.required</code>) result was accessed before query results were calculated or query has no matches.</p><p>This can happen in two distinct situations:</p><ul><li>query results were accessed before a given query could collect results;</li><li>a query was executed but didn&#39;t match any nodes and has no results as a consequence.</li></ul><p>Content queries and view queries each calculate their results at different points in time:</p><ul><li><code>contentChild</code> results are available after a <em>host</em> view (template where a directive declaring a query is used) is created;</li><li><code>viewChild</code> results are available after a template of a component declaring a query is created.</li></ul><p>Accessing query results before they&#39;re available results in the error described on this page. Most notably, query results are <em>never</em> available in a constructor of the component or directive declaring a query.</p><h2 id="fixing-the-error" tabindex="-1">Fixing the error <a class="header-anchor" href="#fixing-the-error" aria-label="Permalink to &quot;Fixing the error&quot;">​</a></h2><p><code>contentChild</code> query results can be accessed in the <code>AfterContentChecked</code> lifecycle hook, or later. <code>viewChild</code> query results can be accessed in the <code>AfterViewChecked</code> lifecycle hook, or later.</p><p>Make sure that a required query matches at least one node and has results at all. You can verify this by accessing query results in the lifecycle hooks listed above.</p>',10)]))}const p=r(s,[["render",l]]);export{q as __pageData,p as default};
